<?php $success=Session::flash('success'); ?>
<?php if($success): ?><div class="alert success"><?= h($success) ?></div><?php endif; ?>
<?php if($loadError): ?><div class="alert error"><?= h($loadError) ?></div><?php endif; ?>
<section class="page-heading"><div><p class="eyebrow">COMPANY STRUCTURE</p><h2>Departments</h2><p class="muted">Create departments for each company before assigning employees.</p></div><?php if($companies): ?><a class="button link-button" href="/departments/create?company=<?= h($companyId) ?>">Add department</a><?php endif; ?></section>
<?php if($companies): ?>
<form method="get" class="selector-card card"><div class="selectors"><label>Company<select name="company" onchange="this.form.submit()"><?php foreach($companies as $company):$id=(string)($company['id']??'');?><option value="<?= h($id) ?>" <?= $id===$companyId?'selected':'' ?>><?= h((string)($company['legal_name']??'Company')) ?></option><?php endforeach;?></select></label></div></form>
<?php if($departments): ?><section class="table-card card"><div class="table-wrap"><table><thead><tr><th>Department</th><th>Code</th><th>Employees</th><th>Status</th></tr></thead><tbody><?php foreach($departments as $d):?><tr><td><strong><?= h((string)$d['name']) ?></strong><span class="muted"><?= h((string)($d['description']??'')) ?></span></td><td><?= h((string)($d['code']??'—')) ?></td><td><?= h((string)($d['employee_count']??0)) ?></td><td><span class="status status-approved"><?= ($d['is_active']??false)?'ACTIVE':'INACTIVE' ?></span></td></tr><?php endforeach;?></tbody></table></div></section><?php else:?><section class="empty card"><p class="eyebrow">NO DEPARTMENTS YET</p><h2>Set up your company structure</h2><p class="muted">Departments are company-specific and can be selected when creating employees.</p><a class="button link-button" href="/departments/create?company=<?= h($companyId) ?>">Add department</a></section><?php endif;?>
<?php else:?><section class="empty card"><h2>Create a company first</h2><a class="button link-button" href="/companies/create">Create company</a></section><?php endif;?>